#### dynamic programming with memoization

```cpp
#include <string>
#include <algorithm>
#include <unordered_map>

int maxPalinSubsequence(std::string s, int i, int j, std::unordered_map<std::string, int> &memo) {
  std::string key = std::to_string(i) + "," + std::to_string(j);

  if (memo.count(key) > 0) {
    return memo[key];
  }

  if (i == j) {
    return 1;
  }

  if (i > j) {
    return 0;
  }

  if (s[i] == s[j]) {
    memo[key] = 2 + maxPalinSubsequence(s, i + 1, j - 1, memo);
  } else {
    memo[key] = std::max(maxPalinSubsequence(s, i + 1, j, memo), maxPalinSubsequence(s, i, j - 1, memo));
  }
  return memo[key];
}

int maxPalinSubsequence(std::string s) {
  std::unordered_map<std::string, int> memo;
  return maxPalinSubsequence(s, 0, s.length() - 1, memo);
}
```

- n = length of the string
- Time: O(n^2)
- Space: O(n^2)
